import { registerLifecycleHooks, start } from "workflow/api";
import { getWorld } from "workflow/runtime";
import { probe } from "../../common/world.ts";
// @ts-ignore generated by `workflow build`
import * as flow from "./.well-known/workflow/v1/flow.mjs";
import { s1 } from "./workflows/s1.ts";

// run/post: the only run-level hook the SDK has. Fire-and-forget, best-effort.
registerLifecycleHooks({
  onRunCompleted: async ({ run, workflowName }) => {
    if (workflowName.endsWith("//s1")) await probe(process.env.RUN_ID!, "mw", "run/post");
  },
  onRunFailed: async ({ workflowName }) => {
    if (workflowName.endsWith("//s1")) await probe(process.env.RUN_ID!, "mw", "run/post");
  },
});

Bun.serve({ port: Number(process.env.PORT), routes: { "/.well-known/workflow/v1/flow": { POST: flow.POST } } });
const world = await getWorld();
await world.start?.();
process.on("SIGTERM", async () => {
  await (world as any).close?.().catch(() => {});
  process.exit(0);
});
if (process.env.START === "1") await start(s1, [process.env.RUN_ID!]);
